def post(times, result):
    token_arrivals = [i * 4 for i in range(1, (len(times) + 3) // 4)]
    tokens = 3
    last_token_arrival = 0
    admitted_requests = 0
    for time in times:
        if time < last_token_arrival:
            return False
        token_interval = (time - last_token_arrival) // 4
        tokens = min(3, tokens + token_interval)
        last_token_arrival = time
        if tokens > 0:
            tokens -= 1
            admitted_requests += 1
    return result == admitted_requests
